  "btn16_4_6__b": "若你們隊伍中有巫者 (The Witch)，但沒有典獄長 (The Warden)",
  "btn16_4_6__c": "若你們隊伍中同時有巫者 (The Witch)與典獄長 (The Warden)",
  "btn16_4_6__d": "否則",
  "btn16_4_7__a": "要求見見那名巫者 (The Witch)",
  "btn16_4_7__b": "否則",
